use counter::Counter;

#[test]
fn test_add_and_count() {
    let mut c: Counter<&str> = Counter::new();
    c.add("apple");
    c.add("banana");
    c.add("apple");
    assert_eq!(c.count(&"apple"), 2);
    assert_eq!(c.count(&"banana"), 1);
    assert_eq!(c.count(&"cherry"), 0);
}

#[test]
fn test_add_many() {
    let mut c: Counter<i32> = Counter::new();
    c.add_many([1, 2, 2, 3, 3, 3]);
    assert_eq!(c.count(&3), 3);
    assert_eq!(c.count(&2), 2);
    assert_eq!(c.count(&1), 1);
}

#[test]
fn test_total() {
    let mut c: Counter<char> = Counter::new();
    c.add_many(['a', 'b', 'a', 'c']);
    assert_eq!(c.total(), 4);
}

#[test]
fn test_most_common() {
    let mut c: Counter<&str> = Counter::new();
    c.add_many(["x", "y", "x", "z", "x", "y"]);
    let top = c.most_common(2);
    assert_eq!(top.len(), 2);
    assert_eq!(top[0], ("x", 3));
    assert_eq!(top[1], ("y", 2));
}

#[test]
fn test_most_common_fewer_than_n() {
    let mut c: Counter<u8> = Counter::new();
    c.add(1);
    c.add(2);
    // asking for top-5 when only 2 distinct items exist
    let top = c.most_common(5);
    assert_eq!(top.len(), 2);
}

#[test]
fn test_empty_counter() {
    let c: Counter<i32> = Counter::new();
    assert_eq!(c.total(), 0);
    assert_eq!(c.count(&42), 0);
    assert!(c.most_common(3).is_empty());
}

