Create src/lib.rs implementing a generic frequency counter.

use std::collections::HashMap;

pub struct Counter<T> { ... }

impl<T: Eq + std::hash::Hash + Clone + Ord> Counter<T> {
    pub fn new() -> Self
    pub fn add(&mut self, item: T)
    pub fn add_many(&mut self, items: impl IntoIterator<Item = T>)
    pub fn count(&self, item: &T) -> usize     // 0 for unseen items
    pub fn most_common(&self, n: usize) -> Vec<(T, usize)>  // descending by count; ties broken by item Ord ascending; truncated to n
    pub fn total(&self) -> usize               // sum of all counts
}

All 6 tests in tests/counter_test.rs must pass.
Run: cargo test
